changeSet.sql:
-- Add phone column to store phone number during verify flow
ALTER TABLE "user".device 
ADD COLUMN IF NOT EXISTS phone TEXT;

-- Add is_verify_device flag to distinguish temporary verify devices
ALTER TABLE "user".device 
ADD COLUMN IF NOT EXISTS is_verify_device BOOLEAN DEFAULT FALSE;

-- Create index for verify device lookups
CREATE INDEX IF NOT EXISTS idx_device_phone_verify 
ON "user".device(phone) 
WHERE is_verify_device = TRUE AND deleted = FALSE;

CREATE INDEX IF NOT EXISTS idx_device_id_verify 
ON "user".device(id) 
WHERE is_verify_device = TRUE AND deleted = FALSE;
